--
-- Name: grant_pg_cron_access(); Type: FUNCTION; Schema: extensions; Owner: supabase_admin
--

CREATE FUNCTION extensions.grant_pg_cron_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_cron'
  )
  THEN
    grant usage on schema cron to postgres with grant option;

    alter default privileges in schema cron grant all on tables to postgres with grant option;
    alter default privileges in schema cron grant all on functions to postgres with grant option;
    alter default privileges in schema cron grant all on sequences to postgres with grant option;

    alter default privileges for user supabase_admin in schema cron grant all
        on sequences to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on tables to postgres with grant option;
    alter default privileges for user supabase_admin in schema cron grant all
        on functions to postgres with grant option;

    grant all privileges on all tables in schema cron to postgres with grant option;
    revoke all on table cron.job from postgres;
    grant select on table cron.job to postgres with grant option;
  END IF;
END;
$$;


ALTER FUNCTION extensions.grant_pg_cron_access() OWNER TO supabase_admin;

--
-- Name: FUNCTION grant_pg_cron_access(); Type: COMMENT; Schema: extensions; Owner: supabase_admin
--

COMMENT ON FUNCTION extensions.grant_pg_cron_access() IS 'Grants access to pg_cron';


--
-- Name: grant_pg_graphql_access(); Type: FUNCTION; Schema: extensions; Owner: supabase_admin
--

CREATE FUNCTION extensions.grant_pg_graphql_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
    func_is_graphql_resolve bool;
BEGIN
    func_is_graphql_resolve = (
        SELECT n.proname = 'resolve'
        FROM pg_event_trigger_ddl_commands() AS ev
        LEFT JOIN pg_catalog.pg_proc AS n
        ON ev.objid = n.oid
    );

    IF func_is_graphql_resolve
    THEN
        -- Update public wrapper to pass all arguments through to the pg_graphql resolve func
        DROP FUNCTION IF EXISTS graphql_public.graphql;
        create or replace function graphql_public.graphql(
            "operationName" text default null,
            query text default null,
            variables jsonb default null,
            extensions jsonb default null
        )
            returns jsonb
            language sql
        as $$
            select graphql.resolve(
                query := query,
                variables := coalesce(variables, '{}'),
                "operationName" := "operationName",
                extensions := extensions
            );
        $$;

        -- This hook executes when `graphql.resolve` is created. That is not necessarily the last
        -- function in the extension so we need to grant permissions on existing entities AND
        -- update default permissions to any others that are created after `graphql.resolve`
        grant usage on schema graphql to postgres, anon, authenticated, service_role;
        grant select on all tables in schema graphql to postgres, anon, authenticated, service_role;
        grant execute on all functions in schema graphql to postgres, anon, authenticated, service_role;
        grant all on all sequences in schema graphql to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on tables to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on functions to postgres, anon, authenticated, service_role;
        alter default privileges in schema graphql grant all on sequences to postgres, anon, authenticated, service_role;

        -- Allow postgres role to allow granting usage on graphql and graphql_public schemas to custom roles
        grant usage on schema graphql_public to postgres with grant option;
        grant usage on schema graphql to postgres with grant option;
    END IF;

END;
$_$;


ALTER FUNCTION extensions.grant_pg_graphql_access() OWNER TO supabase_admin;

--
-- Name: FUNCTION grant_pg_graphql_access(); Type: COMMENT; Schema: extensions; Owner: supabase_admin
--

COMMENT ON FUNCTION extensions.grant_pg_graphql_access() IS 'Grants access to pg_graphql';


--
-- Name: grant_pg_net_access(); Type: FUNCTION; Schema: extensions; Owner: supabase_admin
--

CREATE FUNCTION extensions.grant_pg_net_access() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF EXISTS (
    SELECT 1
    FROM pg_event_trigger_ddl_commands() AS ev
    JOIN pg_extension AS ext
    ON ev.objid = ext.oid
    WHERE ext.extname = 'pg_net'
  )
  THEN
    IF NOT EXISTS (
      SELECT 1
      FROM pg_roles
      WHERE rolname = 'supabase_functions_admin'
    )
    THEN
      CREATE USER supabase_functions_admin NOINHERIT CREATEROLE LOGIN NOREPLICATION;
    END IF;

    GRANT USAGE ON SCHEMA net TO supabase_functions_admin, postgres, anon, authenticated, service_role;

    IF EXISTS (
      SELECT FROM pg_extension
      WHERE extname = 'pg_net'
      -- all versions in use on existing projects as of 2025-02-20
      -- version 0.12.0 onwards don't need these applied
      AND extversion IN ('0.2', '0.6', '0.7', '0.7.1', '0.8', '0.10.0', '0.11.0')
    ) THEN
      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;
      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SECURITY DEFINER;

      ALTER function net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;
      ALTER function net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) SET search_path = net;

      REVOKE ALL ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;
      REVOKE ALL ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) FROM PUBLIC;

      GRANT EXECUTE ON FUNCTION net.http_get(url text, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
      GRANT EXECUTE ON FUNCTION net.http_post(url text, body jsonb, params jsonb, headers jsonb, timeout_milliseconds integer) TO supabase_functions_admin, postgres, anon, authenticated, service_role;
    END IF;
  END IF;
END;
$$;


ALTER FUNCTION extensions.grant_pg_net_access() OWNER TO supabase_admin;

--
-- Name: FUNCTION grant_pg_net_access(); Type: COMMENT; Schema: extensions; Owner: supabase_admin
--

COMMENT ON FUNCTION extensions.grant_pg_net_access() IS 'Grants access to pg_net';


--
-- Name: pgrst_ddl_watch(); Type: FUNCTION; Schema: extensions; Owner: supabase_admin
--

CREATE FUNCTION extensions.pgrst_ddl_watch() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN SELECT * FROM pg_event_trigger_ddl_commands()
  LOOP
    IF cmd.command_tag IN (
      'CREATE SCHEMA', 'ALTER SCHEMA'
    , 'CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO', 'ALTER TABLE'
    , 'CREATE FOREIGN TABLE', 'ALTER FOREIGN TABLE'
    , 'CREATE VIEW', 'ALTER VIEW'
    , 'CREATE MATERIALIZED VIEW', 'ALTER MATERIALIZED VIEW'
    , 'CREATE FUNCTION', 'ALTER FUNCTION'
    , 'CREATE TRIGGER'
    , 'CREATE TYPE', 'ALTER TYPE'
    , 'CREATE RULE'
    , 'COMMENT'
    )
    -- don't notify in case of CREATE TEMP table or other objects created on pg_temp
    AND cmd.schema_name is distinct from 'pg_temp'
    THEN
      NOTIFY pgrst, 'reload schema';
    END IF;
  END LOOP;
END; $$;


ALTER FUNCTION extensions.pgrst_ddl_watch() OWNER TO supabase_admin;

--
-- Name: pgrst_drop_watch(); Type: FUNCTION; Schema: extensions; Owner: supabase_admin
--

CREATE FUNCTION extensions.pgrst_drop_watch() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  obj record;
BEGIN
  FOR obj IN SELECT * FROM pg_event_trigger_dropped_objects()
  LOOP
    IF obj.object_type IN (
      'schema'
    , 'table'
    , 'foreign table'
    , 'view'
    , 'materialized view'
    , 'function'
    , 'trigger'
    , 'type'
    , 'rule'
    )
    AND obj.is_temporary IS false -- no pg_temp objects
    THEN
      NOTIFY pgrst, 'reload schema';
    END IF;
  END LOOP;
END; $$;


ALTER FUNCTION extensions.pgrst_drop_watch() OWNER TO supabase_admin;

--
-- Name: set_graphql_placeholder(); Type: FUNCTION; Schema: extensions; Owner: supabase_admin
--

CREATE FUNCTION extensions.set_graphql_placeholder() RETURNS event_trigger
    LANGUAGE plpgsql
    AS $_$
    DECLARE
    graphql_is_dropped bool;
    BEGIN
    graphql_is_dropped = (
        SELECT ev.schema_name = 'graphql_public'
        FROM pg_event_trigger_dropped_objects() AS ev
        WHERE ev.schema_name = 'graphql_public'
    );

    IF graphql_is_dropped
    THEN
        create or replace function graphql_public.graphql(
            "operationName" text default null,
            query text default null,
            variables jsonb default null,
            extensions jsonb default null
        )
            returns jsonb
            language plpgsql
        as $$
            DECLARE
                server_version float;
            BEGIN
                server_version = (SELECT (SPLIT_PART((select version()), ' ', 2))::float);

                IF server_version >= 14 THEN
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql extension is not enabled.'
                            )
                        )
                    );
                ELSE
                    RETURN jsonb_build_object(
                        'errors', jsonb_build_array(
                            jsonb_build_object(
                                'message', 'pg_graphql is only available on projects running Postgres 14 onwards.'
                            )
                        )
                    );
                END IF;
            END;
        $$;
    END IF;

    END;
$_$;


ALTER FUNCTION extensions.set_graphql_placeholder() OWNER TO supabase_admin;

--
-- Name: FUNCTION set_graphql_placeholder(); Type: COMMENT; Schema: extensions; Owner: supabase_admin
--

COMMENT ON FUNCTION extensions.set_graphql_placeholder() IS 'Reintroduces placeholder function for graphql_public.graphql';


--
-- Name: get_auth(text); Type: FUNCTION; Schema: pgbouncer; Owner: supabase_admin
--

CREATE FUNCTION pgbouncer.get_auth(p_usename text) RETURNS TABLE(username text, password text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
  BEGIN
      RAISE DEBUG 'PgBouncer auth request: %', p_usename;

      RETURN QUERY
      SELECT
          rolname::text,
          CASE WHEN rolvaliduntil < now()
              THEN null
              ELSE rolpassword::text
          END
      FROM pg_authid
      WHERE rolname=$1 and rolcanlogin;
  END;
  $_$;


ALTER FUNCTION pgbouncer.get_auth(p_usename text) OWNER TO supabase_admin;

--
-- Name: auto_charge_from_advance_simplified(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.auto_charge_from_advance_simplified() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_advance_balance DECIMAL(10,2) := 0;
  v_payment_amount DECIMAL(10,2) := 0;
BEGIN
  -- Обрабатываем только income и expense транзакции для студентов с account_id
  IF (NEW.type = 'income' OR NEW.type = 'expense')
     AND NEW.student_id IS NOT NULL 
     AND NEW.account_id IS NOT NULL 
     AND NEW.amount > 0 THEN
    
    -- Получаем текущий авансовый баланс
    SELECT COALESCE(balance, 0) INTO v_advance_balance
    FROM public.advance_balances
    WHERE student_id = NEW.student_id 
      AND account_id = NEW.account_id;
    
    -- Если есть авансовый баланс, списываем с него
    IF v_advance_balance > 0 THEN
      -- Для expense (возвраты) увеличиваем авансовый баланс
      IF NEW.type = 'expense' THEN
        UPDATE public.advance_balances
        SET balance = balance + NEW.amount,
            updated_at = now()
        WHERE student_id = NEW.student_id 
          AND account_id = NEW.account_id;
      ELSE
        -- Для income (начисления) уменьшаем авансовый баланс
        -- Списываем либо всю сумму начисления, либо весь авансовый баланс (что меньше)
        v_payment_amount := LEAST(NEW.amount, v_advance_balance);
        
        UPDATE public.advance_balances
        SET balance = GREATEST(0, balance - v_payment_amount),
            updated_at = now()
        WHERE student_id = NEW.student_id 
          AND account_id = NEW.account_id;
      END IF;
    END IF;
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.auto_charge_from_advance_simplified() OWNER TO postgres;

--
-- Name: FUNCTION auto_charge_from_advance_simplified(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.auto_charge_from_advance_simplified() IS 'Упрощённая логика: автоматически списывает с авансового баланса при создании income транзакций и увеличивает при expense (возвратах). Без создания advance_payment транзакций.';


--
-- Name: delete_payment_transaction(uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.delete_payment_transaction(p_transaction_id uuid, p_reason text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_payment_record RECORD;
  v_advance_balance DECIMAL(10,2) := 0;
  v_result JSON;
BEGIN
  -- Получаем данные платежа
  SELECT 
    id,
    student_id,
    account_id,
    amount,
    date
  INTO v_payment_record
  FROM public.finance_transactions
  WHERE id = p_transaction_id
    AND type = 'payment';
  
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Payment transaction not found: %', p_transaction_id;
  END IF;
  
  -- Если нет student_id или account_id, просто удаляем платеж
  IF v_payment_record.student_id IS NULL OR v_payment_record.account_id IS NULL THEN
    DELETE FROM public.finance_transactions
    WHERE id = p_transaction_id;
    
    v_result := json_build_object(
      'deleted_payment_amount', v_payment_record.amount::numeric,
      'remaining_advance_balance', 0::numeric,
      'message', 'Payment deleted without advance rollback due to missing student_id or account_id'
    );
    
    RETURN v_result;
  END IF;

  -- Уменьшаем авансовый баланс на сумму платежа
  UPDATE public.advance_balances
  SET balance = GREATEST(0, balance - v_payment_record.amount),
      updated_at = now()
  WHERE student_id = v_payment_record.student_id
    AND account_id = v_payment_record.account_id;

  -- Получаем оставшийся авансовый баланс
  SELECT COALESCE(balance, 0) INTO v_advance_balance
  FROM public.advance_balances
  WHERE student_id = v_payment_record.student_id
    AND account_id = v_payment_record.account_id;

  -- Удаляем сам платёж
  DELETE FROM public.finance_transactions
  WHERE id = p_transaction_id;
  
  -- Возвращаем результат
  v_result := json_build_object(
    'deleted_payment_amount', v_payment_record.amount::numeric,
    'remaining_advance_balance', COALESCE(v_advance_balance, 0)::numeric
  );
  
  RETURN v_result;
EXCEPTION
  WHEN OTHERS THEN
    RAISE EXCEPTION 'Error in delete_payment_transaction: % (SQLSTATE: %)', SQLERRM, SQLSTATE;
END;
$$;


ALTER FUNCTION public.delete_payment_transaction(p_transaction_id uuid, p_reason text) OWNER TO postgres;

--
-- Name: FUNCTION delete_payment_transaction(p_transaction_id uuid, p_reason text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.delete_payment_transaction(p_transaction_id uuid, p_reason text) IS 'Упрощённая логика: удаляет платёж и уменьшает авансовый баланс. Без отката распределения по активностям.';


--
-- Name: handle_new_user_profile(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_new_user_profile() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  profiles_count integer;
  profile_exists boolean;
BEGIN
  -- Проверяем, существует ли уже профиль (на случай race condition)
  SELECT EXISTS(SELECT 1 FROM public.user_profiles WHERE id = NEW.id) INTO profile_exists;
  
  IF profile_exists THEN
    -- Профиль уже существует, ничего не делаем
    RETURN NEW;
  END IF;

  -- Подсчитываем количество существующих профилей
  SELECT COUNT(*) INTO profiles_count FROM public.user_profiles;

  -- Пытаемся создать профиль
  BEGIN
    INSERT INTO public.user_profiles (id, full_name, parent_name, child_name, role, is_active)
    VALUES (
      NEW.id,
      COALESCE(
        NEW.raw_user_meta_data->>'full_name', 
        NEW.raw_user_meta_data->>'name',
        NEW.raw_user_meta_data->>'parent_name'
      ),
      NEW.raw_user_meta_data->>'parent_name',
      NEW.raw_user_meta_data->>'child_name',
      CASE WHEN profiles_count = 0 THEN 'owner' ELSE 'newregistration' END,
      CASE WHEN profiles_count = 0 THEN true ELSE false END
    )
    ON CONFLICT (id) DO NOTHING;
  EXCEPTION
    WHEN OTHERS THEN
      -- Логируем ошибку, но не прерываем создание пользователя
      -- Профиль будет создан позже через fetchOrCreateProfile в клиентском коде
      RAISE WARNING 'Failed to create user profile for user %: %', NEW.id, SQLERRM;
      -- Возвращаем NEW, чтобы не блокировать создание пользователя
      RETURN NEW;
  END;

  RETURN NEW;
END;
$$;


ALTER FUNCTION public.handle_new_user_profile() OWNER TO postgres;

--
-- Name: FUNCTION handle_new_user_profile(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.handle_new_user_profile() IS 'Автоматически создает профиль пользователя при регистрации. При ошибке не блокирует создание пользователя, профиль будет создан позже через клиентский код.';


--
-- Name: handle_payment_transaction(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.handle_payment_transaction() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Просто увеличиваем авансовый баланс при создании платежа
  -- Без распределения по активностям
  IF NEW.type = 'payment' 
     AND NEW.student_id IS NOT NULL 
     AND NEW.account_id IS NOT NULL 
     AND NEW.amount > 0 THEN
    
    -- Увеличиваем авансовый баланс
    INSERT INTO public.advance_balances (student_id, account_id, balance)
    VALUES (NEW.student_id, NEW.account_id, NEW.amount)
    ON CONFLICT (student_id, account_id)
    DO UPDATE SET
      balance = advance_balances.balance + NEW.amount,
      updated_at = now();
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION public.handle_payment_transaction() OWNER TO postgres;

--
-- Name: FUNCTION handle_payment_transaction(); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.handle_payment_transaction() IS 'Упрощённая логика: просто увеличивает авансовый баланс при создании платежа. Без распределения по активностям.';


--
-- Name: recalculate_advance_balance_for_student(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.recalculate_advance_balance_for_student(p_student_id uuid, p_account_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_advance_balance DECIMAL(10,2) := 0;
  v_total_income DECIMAL(10,2) := 0;
  v_total_expense DECIMAL(10,2) := 0;
  v_charge_amount DECIMAL(10,2) := 0;
  v_last_payment_date DATE;
  v_charged_amount DECIMAL(10,2) := 0;
  v_advance_before DECIMAL(10,2) := 0;
  v_result JSON;
BEGIN
  -- Получаем текущий авансовый баланс
  SELECT COALESCE(balance, 0) INTO v_advance_balance
  FROM public.advance_balances
  WHERE student_id = p_student_id 
    AND account_id = p_account_id;
  
  -- Если нет авансового баланса, ничего не делаем
  IF v_advance_balance <= 0 THEN
    RETURN json_build_object(
      'message', 'No advance balance to recalculate',
      'advance_balance', 0::numeric,
      'total_income', 0::numeric,
      'total_expense', 0::numeric
    );
  END IF;
  
  -- Находим дату последнего платежа для этого студента и счёта
  SELECT MAX(date) INTO v_last_payment_date
  FROM public.finance_transactions
  WHERE student_id = p_student_id
    AND account_id = p_account_id
    AND type = 'payment'
    AND amount > 0;
  
  -- Если платежей не было, ничего не делаем
  IF v_last_payment_date IS NULL THEN
    RETURN json_build_object(
      'message', 'No payments found for this student and account',
      'advance_balance', v_advance_balance::numeric
    );
  END IF;
  
  -- Считаем сумму всех income транзакций, созданных после последнего платежа
  SELECT COALESCE(SUM(amount), 0) INTO v_total_income
  FROM public.finance_transactions
  WHERE student_id = p_student_id
    AND account_id = p_account_id
    AND type = 'income'
    AND amount > 0
    AND date >= v_last_payment_date;
  
  -- Считаем сумму всех expense транзакций (возвратов), созданных после последнего платежа
  SELECT COALESCE(SUM(amount), 0) INTO v_total_expense
  FROM public.finance_transactions
  WHERE student_id = p_student_id
    AND account_id = p_account_id
    AND type = 'expense'
    AND amount > 0
    AND date >= v_last_payment_date;
  
  -- Чистая сумма начислений (income - expense)
  v_charge_amount := v_total_income - v_total_expense;
  
  -- Если есть начисления, списываем с авансового баланса
  IF v_charge_amount > 0 THEN
    -- Списываем либо всю сумму начислений, либо весь авансовый баланс (что меньше)
    UPDATE public.advance_balances
    SET balance = GREATEST(0, balance - LEAST(v_charge_amount, v_advance_balance)),
        updated_at = now()
    WHERE student_id = p_student_id 
      AND account_id = p_account_id;
  END IF;
  
  -- Сохраняем сумму списанного с авансового баланса
  v_charged_amount := LEAST(v_charge_amount, v_advance_balance);
  v_advance_before := v_advance_balance;
  
  -- Получаем обновлённый авансовый баланс
  SELECT COALESCE(balance, 0) INTO v_advance_balance
  FROM public.advance_balances
  WHERE student_id = p_student_id 
    AND account_id = p_account_id;
  
  -- Возвращаем результат
  v_result := json_build_object(
    'message', 'Advance balance recalculated',
    'advance_balance_before', v_advance_before::numeric,
    'advance_balance_after', v_advance_balance::numeric,
    'total_income', v_total_income::numeric,
    'total_expense', v_total_expense::numeric,
    'charge_amount', v_charge_amount::numeric,
    'charged_from_advance', v_charged_amount::numeric
  );
  
  RETURN v_result;
END;
$$;


ALTER FUNCTION public.recalculate_advance_balance_for_student(p_student_id uuid, p_account_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION recalculate_advance_balance_for_student(p_student_id uuid, p_account_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.recalculate_advance_balance_for_student(p_student_id uuid, p_account_id uuid) IS 'Пересчитывает авансовый баланс для существующих income/expense транзакций. Списывает с авансового баланса сумму всех начислений (income - expense).';


